-- Spec 005 (R-005.50): al insertar su comentario, la persona no escribe lo que decide el coach. Generado con npm run db:generate desde lib/db/schema.ts.
ALTER POLICY "profile_events_insert_persona_feedback" ON "app"."profile_events" TO authenticated WITH CHECK ((select private.app_is_persona_of("app"."profile_events"."engagement_id")) and "app"."profile_events"."created_by" = (select auth.uid()) and "app"."profile_events"."tipo" = 'no_me_representa' and "app"."profile_events"."status" = 'proposed' and (select private.app_has_consent("app"."profile_events"."engagement_id")) and "app"."profile_events"."session_id" is null and "app"."profile_events"."approved_payload" is null and "app"."profile_events"."decided_by" is null and "app"."profile_events"."decided_at" is null and "app"."profile_events"."prompt_version" is null and "app"."profile_events"."model" is null and "app"."profile_events"."perfil_version_base" is null and "app"."profile_events"."plan_base_id" is null and "app"."profile_events"."resuelto_por_evento" is null and "app"."profile_events"."resuelto_por_plan" is null and "app"."profile_events"."created_at" = now());